<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany;
class SchoolAsset extends Model { public const CONDITIONS=['baik'=>'Baik','perlu_perbaikan'=>'Perlu perbaikan','rusak'=>'Rusak']; public const STATUSES=['tersedia'=>'Tersedia','dipinjam'=>'Dipinjam','perawatan'=>'Perawatan','dihapuskan'=>'Dihapuskan']; protected $fillable=['code','name','category','location','quantity','condition','status','acquired_on','acquisition_value','note']; protected $casts=['acquired_on'=>'date','acquisition_value'=>'decimal:2']; public function loans(): HasMany { return $this->hasMany(AssetLoan::class); } public function maintenances(): HasMany { return $this->hasMany(AssetMaintenance::class); } }
